commands.command:
$src = "C:\Project"; $dest = "C:\Project-flat"
New-Item -ItemType Directory -Path $dest -Force | Out-Null
Get-ChildItem $src -Recurse -File | ForEach-Object {
    $name = $_.Name; $i = 1
    while (Test-Path (Join-Path $dest $name)) { $name = "{0}_{1}{2}" -f $_.BaseName, $i++, $_.Extension }
    Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $dest $name)
}

$src = "C:\Project"; $dest = "C:\Project-flat"
New-Item -ItemType Directory -Path $dest -Force | Out-Null
Get-ChildItem $src -Recurse -File | ForEach-Object {
    $name = $_.Name; $i = 1
    while (Test-Path (Join-Path $dest $name)) { $name = "{0}_{1}{2}" -f $_.BaseName, $i++, $_.Extension }
    Move-Item -LiteralPath $_.FullName -Destination (Join-Path $dest $name)
}

Get-ChildItem -Directory | ForEach-Object {
    [pscustomobject]@{ Folder = $_.Name; MB = [math]::Round((Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum / 1MB, 1) }
} | Sort-Object MB -Descending

Get-ChildItem -File | ForEach-Object {
    $dir = $_.Extension.TrimStart('.').ToUpper()
    if (-not $dir) { $dir = "NOEXT" }
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
    Move-Item -LiteralPath $_.FullName -Destination $dir
}

Get-ChildItem -File | ForEach-Object {
    $d = $_.LastWriteTime.ToString("yyyy-MM")
    New-Item -ItemType Directory -Path $d -Force | Out-Null
    Move-Item -LiteralPath $_.FullName -Destination $d
}

$root = "$HOME\Downloads"
$map = @{ Images = '.jpg','.jpeg','.png','.gif','.webp'; PDFs = '.pdf'; Archives = '.zip','.rar','.7z'; Docs = '.docx','.xlsx','.pptx','.txt' }
Get-ChildItem $root -File | ForEach-Object {
    $ext = $_.Extension.ToLower()
    $folder = $map.Keys | Where-Object { $map[$_] -contains $ext } | Select-Object -First 1
    if ($folder) {
        $target = Join-Path $root $folder
        New-Item -ItemType Directory -Path $target -Force | Out-Null
        Move-Item -LiteralPath $_.FullName -Destination $target
    }
}

Get-ChildItem C:\Project -Recurse -File -Include *.js,*.html,*.css,*.json | ForEach-Object {
    $t = Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8
    if ($t.Contains("old-api.example.com")) {
        $t.Replace("old-api.example.com", "new-api.example.com") | Set-Content -LiteralPath $_.FullName -Encoding UTF8 -NoNewline
    }
}
